// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Try to transfer ownership from non-owner (address(1))
        vm.prank(address(1));
        c.transferOwnership(address(1));
        // Now call owned() as address(1)
        vm.prank(address(1));
        c.owned();
        // Assert that the owner address is still the zero address (the initial owner)
        // In the reference (correct) contract: transferOwnership reverts, so owner stays 0
        // In the bug: transferOwnership succeeds, so owner becomes address(1) and owned() doesn't revert
        assertTrue(c.owner() == address(0));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First attempt: non-owner calls transferOwnership
        vm.prank(address(2));
        c.transferOwnership(address(2));

        // Now address(2) attempts to call owned()
        vm.prank(address(2));
        bool ok;
        try c.owned() { ok = true; } catch { ok = false; }
        // Reference: transferOwnership reverted, so owner remains address(0),
        //   and owned() reverts because msg.sender (address(2)) != owner.
        // Bug: transferOwnership succeeded, owner = address(2), so owned() succeeds.
        assertTrue(!ok, "owned() should revert for non-owner");
    }
}

