// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address nonOwner = address(1);
        vm.prank(nonOwner);
        // transferOwnership will revert in reference, succeed in buggy
        // Wrap the first call in try/catch to proceed regardless
        bool ok;
        try c.transferOwnership(nonOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // In the reference, it reverts, so ok == false
        // In the buggy, it succeeds, so ok == true and owner becomes nonOwner
        // Now call owned() as nonOwner to solidify the state diff
        vm.prank(nonOwner);
        c.owned();
        // The divergence: owner() returns nonOwner in buggy, address(0) in reference
        assertTrue(c.owner() == nonOwner);
    }
}

