// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        address bob = address(0x5678);

        // Initially owner is address(0). Set owner to alice.
        vm.prank(address(0));
        c.transferOwnership(alice);

        // Now alice transfers to bob.
        vm.prank(alice);
        c.transferOwnership(bob);

        // Now alice (who is no longer owner) calls owned(). In reference, it reverts.
        // In mutant, it changes owner to alice.
        vm.prank(alice);
        bool success;
        try c.owned() {
            success = true;
        } catch {
            success = false;
        }

        // In reference, alice is not owner so revert -> success = false.
        // In mutant, no revert (owner changed) -> success = true.
        assertTrue(success == false);
    }
}
